import itertools
events=[]
class Key:
 def __init__(self,n):self.n=n
 def __eq__(self,other):events.append((self.n,other.n));return True
try:
 it=list(itertools.groupby([1,2],key=lambda x:[Key(x)]))
 print(len(it) if isinstance(it,list) else next(it,None) is None,events)
except Exception as e:print(type(e).__name__,events)

